   747 |     fn closure(self: *Dfa, at_bol: bool, at_eol: bool) Allocator.Error![]const u32 {
   748 |         self.gen +%= 1;
   749 |         if (self.gen == 0) {
   750 |             @memset(self.mark, 0);
   751 |             self.gen = 1;
   752 |         }
   753 |         self.work.clearRetainingCapacity();
   754 |         self.stack.clearRetainingCapacity();
   755 |         for (self.seeds.items) |s| try self.stack.append(self.gpa, s);
   756 |         const nodes = self.prog.nodes;
   757 |         while (self.stack.pop()) |id| {
   758 |             if (self.mark[id] == self.gen) continue;
   759 |             self.mark[id] = self.gen;
   760 |             const n = nodes[id];
   761 |             switch (n.kind) {
   762 |                 .set => try self.work.append(self.gpa, id),
   763 |                 .split => {
   764 |                     try self.stack.append(self.gpa, n.out1);
   765 |                     try self.stack.append(self.gpa, n.out);
   766 |                 },
   767 |                 .bol => if (at_bol) try self.stack.append(self.gpa, n.out),
   768 |                 .eol => if (at_eol) {
   769 |                     try self.stack.append(self.gpa, n.out);
   770 |                 } else {
   771 |                     try self.work.append(self.gpa, id);
   772 |                 },
   773 |                 // A word-boundary node is KEPT in the state, exactly like `eol`: it
   774 |                 // cannot be resolved while building the state (the byte that
   775 |                 // settles it has not been consumed yet), so `step` resolves it
   776 |                 // on the next byte.
   777 |                 .wb => try self.work.append(self.gpa, id),
   778 |                 .nwb => try self.work.append(self.gpa, id),
   779 |                 .match => try self.work.append(self.gpa, id),
   780 |             }
   781 |         }
>  782 |         std.mem.sort(u32, self.work.items, {}, std.sort.asc(u32));
   783 |         return self.work.items;
   784 |     }
